+use oxc_allocator::Allocator;
+use oxc_codegen::{Codegen, CodegenOptions};
+use oxc_minifier::{CompressOptions, Compressor};
+use oxc_parser::Parser;
+use oxc_span::SourceType;
+
+fn run(src: &str) -> String {
+    let allocator = Allocator::default();
+    let ret = Parser::new(&allocator, src, SourceType::mjs()).parse();
+    let mut program = ret.program;
+    Compressor::new(&allocator).build(&mut program, CompressOptions::default());
+    Codegen::new()
+        .with_options(CodegenOptions { minify: false, ..CodegenOptions::default() })
+        .build(&program)
+        .code
+}
+
+fn main() {
+    let cases = [
+        "x = new RegExp('a' + 'b')",
+        "x = new RegExp('a' + 'b', 'g')",
+        "var inner = new Set([]); x = new WeakSet(inner);",
+        "x = new Map([])",
+    ];
+    for c in cases {
+        let out1 = run(c);
+        // idempotency: run on output again
+        let out2 = run(&out1);
+        println!("IN : {c}");
+        println!("OUT: {out1}");
+        println!("2X : {out2}");
+        println!("idempotent: {}", out1.trim() == out2.trim());
+        println!("---");
+    }
+}
